                            for y in range(r, r + 5)
                            for x in range(c, c + 5)
                        ):
                            hit = (r, c)
                        break
                if hit is not None:
                    break

            if hit is not None:
                r, c = hit
                for y in range(r, r + 5):
                    for x in range(c, c + 5):
                        board[y][x] = "S"

                # Remove a separator only where sky exists beyond it.
                for x in range(c, c + 5):
                    if r >= 2 and board[r - 2][x] == "S":
                        board[r - 1][x] = "S"
                    if r + 6 < 63 and board[r + 6][x] == "S":
                        board[r + 5][x] = "S"
                for y in range(r, r + 5):
                    if c >= 2 and board[y][c - 2] == "S":
