                    if offset is not None:
                        for x in range(offset, 64, 6):
                            row[x] = "G"

                    if y < 6:
                        row[13:54] = ["S"] * 41
                    elif y >= 13:
                        row[31:54] = ["S"] * 23

                    if 7 <= y <= 11 or 13 <= y <= 17:
                        pattern = (
                            "GNNNG" if y % 6 in (1, 5) else "NNNNN"
                        )
                        for x in (13, 19, 25):
                            row[x:x + 5] = list(pattern)

                    board[y] = row

            middle = "BYbbB" if name == "LEFT" else "BbbYB"
            sprite = ("BBbBB", middle, middle, "BBbBB", "SBBBS")
            for dy, pixels in enumerate(sprite):
                board[r + dy][nc:nc + 5] = list(pixels)

    return ["".join(row) for row in board]

